# Telemetry test for inventory-api: generated by otel-as-code v0.21.2 (/otel-test)
# Re-run /otel-test --force to regenerate. /otel-uninstrument removes this file.
#
# What this protects: POST /inventory/reserve must keep producing the telemetry listed in
# EXPECTED below. A refactor can rename a handler, drop a middleware or lose the line that
# instruments the app without breaking any other test. The dashboards and alerts then go quiet
# and nothing fails. This test fails instead, and says which span or metric is missing.
#
# How it works: it imports the app the server runs (main:app) and calls it in this process,
# with OpenTelemetry's in-memory exporter in place of the real one. No server is started,
# nothing leaves the machine and no backend is needed.
#
# Run it: python -m unittest test_otel     (pytest runs it too: python -m pytest test_otel.py)
# Run it in its own process: OpenTelemetry can be set up once per process, so a test that
# imported the app earlier in the same run would leave this one with nothing to read.
import importlib
import json
import os
import sys
import unittest

# The service's own bootstrap must not export anywhere during the test.
for _signal in ("TRACES", "METRICS", "LOGS"):
    os.environ[f"OTEL_{_signal}_EXPORTER"] = "none"
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from opentelemetry import metrics, trace
from opentelemetry.sdk.metrics import MeterProvider
from opentelemetry.sdk.metrics.export import InMemoryMetricReader
from opentelemetry.sdk.trace import TracerProvider
from opentelemetry.sdk.trace.export import SimpleSpanProcessor
from opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter

APP = ["main", "app"]
BOOTSTRAP = 'tracing'
INTERFACE = "asgi"
REQUEST = json.loads('{"method": "POST", "path": "/inventory/reserve", "expectStatus": 200, "json": {"sku": "s1", "quantity": 2, "warehouse": "w"}}')
EXPECTED = {
    "serverSpan": "POST /inventory/reserve",
    "spans": ["inventory.reserve_stock"],
    "metrics": ["com.example.inventory.reservations", "com.example.inventory.reserved_quantity"],
}

_spans = InMemorySpanExporter()
_tracer_provider = TracerProvider()
_tracer_provider.add_span_processor(SimpleSpanProcessor(_spans))
trace.set_tracer_provider(_tracer_provider)
_reader = InMemoryMetricReader()
metrics.set_meter_provider(MeterProvider(metric_readers=[_reader]))

_app = getattr(importlib.import_module(APP[0]), APP[1])


def _body():
    return json.dumps(REQUEST["json"]).encode() if "json" in REQUEST else b""


def _call_asgi():
    import asyncio

    path, _, query = REQUEST["path"].partition("?")
    body = _body()
    headers = [(b"host", b"testserver")]
    if body:
        headers += [(b"content-type", b"application/json"), (b"content-length", str(len(body)).encode())]
    scope = {
        "type": "http", "asgi": {"version": "3.0"}, "http_version": "1.1", "method": REQUEST["method"],
        "scheme": "http", "path": path, "raw_path": path.encode(), "query_string": query.encode(),
        "root_path": "", "headers": headers, "client": ("127.0.0.1", 50000), "server": ("testserver", 80),
    }
    result = {}

    async def run():
        delivered = asyncio.Event()

        async def receive():
            if not delivered.is_set():
                delivered.set()
                return {"type": "http.request", "body": body, "more_body": False}
            await asyncio.sleep(3600)

        async def send(message):
            if message["type"] == "http.response.start":
                result["status"] = message["status"]

        await _app(scope, receive, send)

    asyncio.run(run())
    return result.get("status")


def _call_wsgi():
    import io
    from wsgiref.util import setup_testing_defaults

    path, _, query = REQUEST["path"].partition("?")
    body = _body()
    environ = {"REQUEST_METHOD": REQUEST["method"], "PATH_INFO": path, "QUERY_STRING": query,
               "wsgi.input": io.BytesIO(body), "CONTENT_LENGTH": str(len(body))}
    if body:
        environ["CONTENT_TYPE"] = "application/json"
    setup_testing_defaults(environ)
    result = {}

    def start_response(status, headers, exc_info=None):
        result["status"] = int(status.split()[0])

    chunks = _app(environ, start_response)
    try:
        for _ in chunks:
            pass
    finally:
        if hasattr(chunks, "close"):
            chunks.close()
    return result.get("status")


class TelemetryTest(unittest.TestCase):
    def test_request_still_emits_its_telemetry(self):
        self.assertIs(
            trace.get_tracer_provider(), _tracer_provider,
            "OpenTelemetry was already set up in this process before this test loaded, so its spans "
            "cannot be read here. Run this file in its own process: python -m unittest test_otel",
        )
        if BOOTSTRAP:
            # This test reads telemetry in memory, so it would still pass with the bootstrap gone,
            # while production exported nothing. Importing the app must import the bootstrap.
            self.assertIn(
                BOOTSTRAP, sys.modules,
                f"Importing {APP[0]} no longer imports the OpenTelemetry bootstrap ({BOOTSTRAP}), so the "
                f"running service would export no telemetry at all.",
            )
        status = (_call_asgi if INTERFACE == "asgi" else _call_wsgi)()
        what = f"{REQUEST['method']} {REQUEST['path']}"
        self.assertEqual(
            status, REQUEST["expectStatus"],
            f"{what} answered {status}, expected {REQUEST['expectStatus']}. This test needs that request "
            f"to succeed before it can check the telemetry.",
        )
        finished = _spans.get_finished_spans()
        server = next((s for s in finished
                       if s.name == EXPECTED["serverSpan"] and s.kind == trace.SpanKind.SERVER), None)
        missing = []
        if server is None:
            missing.append(f"the request's own span \"{EXPECTED['serverSpan']}\"")
        for name in EXPECTED["spans"]:
            named = [s for s in finished if s.name == name]
            if not any(server is None or s.context.trace_id == server.context.trace_id for s in named):
                missing.append(f"span \"{name}\"" + (" (it was made, but outside the request's trace)" if named else ""))
        data = _reader.get_metrics_data()
        seen_metrics = sorted({m.name for rm in (data.resource_metrics if data else [])
                               for sm in rm.scope_metrics for m in sm.metrics})
        missing += [f"metric \"{name}\"" for name in EXPECTED["metrics"] if name not in seen_metrics]
        if missing:
            seen_spans = sorted({s.name for s in finished})
            hint = (
                "No telemetry was produced at all, so the app is probably no longer instrumented: check "
                "that the module the server runs still imports the bootstrap and instruments the app."
                if not seen_spans and not seen_metrics else
                f"Spans that were made: {', '.join(seen_spans) or '(none)'}\n"
                f"Metrics that were made: {', '.join(seen_metrics) or '(none)'}"
            )
            self.fail(f"Missing telemetry for {what}:\n  - " + "\n  - ".join(missing) + "\n" + hint)


if __name__ == "__main__":
    unittest.main()
